class BankAccount:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount
        print('{}存入{}元，余额{}元'.format(self.owner, amount, self.balance))

    def withdraw(self, amount):
        if amount > self.balance:
            print('余额不足，{}取款失败'.format(self.owner))
        else:
            self.balance -= amount
            print('{}取出{}元，余额{}元'.format(self.owner, amount, self.balance))

balance = int(input())
acc = BankAccount('小明', balance)
acc.deposit(200)
acc.withdraw(450)
acc.withdraw(300)

