def perm(chars, prefix):
    if len(chars) == 0:
        print(prefix)
        return
    for i in range(len(chars)):
        perm(chars[:i] + chars[i + 1:], prefix + chars[i])

s = sorted(input())
perm(s, '')

def digit_sum(n):
    if n == 0:
        return 0
    return n % 10 + digit_sum(n // 10)

def rev(n, acc=0):
    if n == 0:
        return acc
    return rev(n // 10, acc * 10 + n % 10)

n = int(input())
print(digit_sum(n))
print(rev(n))
